from datetime import datetime,time
from zoneinfo import ZoneInfo

def receivers(labels,instant,holidays,calendar_valid=True):
    if not isinstance(instant,datetime) or instant.tzinfo is None:raise ValueError('aware instant required')
    team=labels.get('team')
    if team not in ('primary','other'):return {'always'}
    try:local=instant.astimezone(ZoneInfo('America/New_York'))
    except Exception:raise ValueError('timezone unavailable')
    holiday=local.date().isoformat() in holidays
    if not calendar_valid:return {'always'}
    if team=='primary' and local.weekday()<5 and not holiday and time(9)<=local.timetz().replace(tzinfo=None)<time(17):return {'primary','always'}
    return {'always'}
```

